const req = $('Richiesta ricevuta').first().json || {};
const q = String(req.Query || '').trim().toLowerCase();
const foglioRaw = String(req.Foglio || '').trim().toLowerCase();
const wanted = foglioRaw ? foglioRaw.split(/[,;|/]+/).map(s => s.trim()).filter(Boolean) : ['prodotti', 'galenici', 'servizi', 'offerte'];
function norm(s) { return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''); }
const nq = norm(q);
const tokens = nq.split(/[^a-z0-9]+/).filter(t => t.length >= 3);
function score(row) {
  const blob = norm(Object.values(row).join(' '));
  if (!nq) return 1;
  if (blob === nq) return 100;
  if (blob.includes(nq) || nq.includes(blob)) return 80;
  let hits = 0;
  for (const t of tokens) if (blob.includes(t)) hits++;
  if (!hits) return 0;
  return 20 + hits * 15;
}
function pack(foglio, rows, nameKeys) {
  if (!wanted.some(w => foglio.toLowerCase().startsWith(w.slice(0, 4)))) return [];
  return rows.map(r => {
    const nome = nameKeys.map(k => r[k]).find(Boolean) || '';
    const s = score({ nome, ...r });
    if (s <= 0) return null;
    const out = { foglio: foglio, nome: String(nome), punteggio: s };
    if (r.categoria) out.categoria = r.categoria;
    if (r.prezzo) out.prezzo = r.prezzo;
    if (r.prezzo_sconto) out.prezzo = r.prezzo_sconto;
    if (r.note) out.note = r.note;
    if (r.descrizione) out.descrizione = r.descrizione;
    if (r.valido_fino) out.valido_fino = r.valido_fino;
    return out;
  }).filter(Boolean);
}
const hits = [
  ...pack('Prodotti', $('Leggi Prodotti').all().map(i => i.json), ['nome']),
  ...pack('Galenici', $('Leggi Galenici').all().map(i => i.json), ['nome']),
  ...pack('Servizi', $('Leggi Servizi').all().map(i => i.json), ['servizio', 'nome']),
  ...pack('Offerte', $('Leggi Offerte').all().map(i => i.json), ['titolo', 'nome']),
].sort((a, b) => b.punteggio - a.punteggio).slice(0, 8);
const risultati = hits.map(({ punteggio, ...rest }) => rest);
return [{ json: { query: q, fogli: wanted, trovati: risultati.length, risultati: risultati, nota: risultati.length ? 'Usa SOLO queste righe. Non inventare prezzi. Se prezzo e da definire, dillo cosi.' : 'Nessuna riga pertinente. Non inventare prodotti o prezzi. Invita a chiamare lo 079 278245.' } }];
